hooks.hook:
//<?php
/**
 * NouN IPTV Keys — Dispatcher Front hook ALL-INLINE (v2.1.5).
 *
 * Estende: \IPS\Dispatcher\Front
 *
 * v2.1.4 diagnostico ha provato che IPS4 plugin loader SCARTA le top-level
 * class declarations fuori da `class hook1`. Quindi: TUTTO il codice del plugin
 * (cipher AES-256-GCM, redeem handler logic) è dichiarato qui come metodi
 * statici di hook1. NIENTE sources/ inlined.
 *
 * Endpoint: POST /?noun_iptv_api=redeem
 *   Body JSON: { code, device_id, ts, sig }
 *   Risposta: JSON { ok, host, username, password, expires_at, max_connections }
 */

if (!\defined('\IPS\SUITE_UNIQUE_KEY')) { exit; }

class hook1 extends _HOOK_CLASS_
{
    /**
     * Override init() del Dispatcher Front. Intercetta ?noun_iptv_api=redeem
     * PRIMA del login wall check (canAccessModule). Permette POST anonimi
     * dal client mobile senza session cookie.
     */
    public function init()
    {
        $apiAction = isset($_GET['noun_iptv_api']) ? (string) $_GET['noun_iptv_api'] : '';
        if ($apiAction === 'redeem') {
            try {
                self::handleRedeem();
            } catch (\Throwable $e) {
                self::sendJson(500, array(
                    'ok' => false,
                    'error' => 'handler_exception',
                    'message' => $e->getMessage(),
                    'file' => basename($e->getFile()),
                    'line' => $e->getLine(),
                    'class' => get_class($e),
                ));
            }
            // handleRedeem chiama sempre sendJson che fa exit
        }
        return parent::init();
    }

    /** Entry point del redeem flow. Stampa JSON + exit. */
    protected static function handleRedeem()
    {
        // POST only
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
            self::sendJson(405, array('ok' => false, 'error' => 'method_not_allowed', 'message' => 'Use POST'));
        }

        // Parse JSON body
        $raw = file_get_contents('php://input');
        $req = json_decode($raw, true);
        if (!is_array($req)) {
            self::sendJson(400, array('ok' => false, 'error' => 'invalid_request', 'message' => 'malformed JSON body'));
        }

        $code     = isset($req['code']) ? preg_replace('/\D+/', '', (string)$req['code']) : '';
        $deviceId = isset($req['device_id']) ? trim((string)$req['device_id']) : '';
        $ts       = isset($req['ts']) ? (int)$req['ts'] : 0;
        $sig      = isset($req['sig']) ? strtolower(trim((string)$req['sig'])) : '';

        if (strlen($code) !== 16 || $deviceId === '' || $sig === '' || $ts === 0) {
            self::audit($code, $deviceId, 'invalid_request', 'missing/invalid fields');
            self::sendJson(400, array('ok' => false, 'error' => 'invalid_request', 'message' => 'missing fields'));
        }

        $ip = isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '0.0.0.0';

        // Rate-limit
        if (self::rateLimited($ip)) {
            self::audit($code, $deviceId, 'rate_limited', "ip=$ip");
            self::sendJson(429, array('ok' => false, 'error' => 'rate_limited', 'message' => 'Troppi tentativi falliti. Riprova tra 1 ora.'));
        }

        // HMAC verify
        $secret = (string)\IPS\Settings::i()->noun_iptv_shared_secret;
        if ($secret === '') {
            self::audit($code, $deviceId, 'config_error', 'shared_secret not set');
            self::sendJson(500, array('ok' => false, 'error' => 'config_error', 'message' => 'Plugin not configured (shared_secret missing in Settings tab)'));
        }
        $payload  = "$code|$deviceId|$ts";
        $expected = hash_hmac('sha256', $payload, $secret);
        if (!hash_equals($expected, $sig)) {
            self::audit($code, $deviceId, 'invalid_signature', 'HMAC mismatch');
            self::sendJson(401, array('ok' => false, 'error' => 'invalid_signature', 'message' => 'Signature mismatch'));
        }

        // Anti-replay window
        $window = max(60, (int)\IPS\Settings::i()->noun_iptv_replay_window_sec);
        $now = time();
        if (abs($now - $ts) > $window) {
            self::audit($code, $deviceId, 'invalid_signature', "ts out of window (|now-ts|=" . abs($now - $ts) . ")");
            self::sendJson(401, array('ok' => false, 'error' => 'invalid_signature', 'message' => 'Timestamp out of window'));
        }

        // Lookup key
        try {
            $key = \IPS\Db::i()->select('*', 'noun_iptv_keys', array('code=?', $code))->first();
        } catch (\UnderflowException $e) {
            self::audit($code, $deviceId, 'key_not_found', '');
            self::sendJson(404, array('ok' => false, 'error' => 'key_not_found', 'message' => 'Code introuvable'));
        }

        // Status check
        if ($key['status'] !== 'active' && $key['status'] !== 'redeemed') {
            self::audit($code, $deviceId, 'key_' . $key['status'], '');
            self::sendJson(403, array('ok' => false, 'error' => "key_{$key['status']}", 'message' => "Code {$key['status']}"));
        }

        // Key expiry
        if (!empty($key['expires_at']) && $key['expires_at'] > 0 && $key['expires_at'] < $now) {
            \IPS\Db::i()->update('noun_iptv_keys', array('status' => 'expired'), array('code=?', $code));
            self::audit($code, $deviceId, 'key_expired', '');
            self::sendJson(403, array('ok' => false, 'error' => 'key_expired', 'message' => 'Code expiré'));
        }

        // Device binding
        if (!empty($key['bound_device_id'])) {
            if ($key['bound_device_id'] !== $deviceId) {
                self::audit($code, $deviceId, 'key_already_redeemed', "bound={$key['bound_device_id']}");
                self::sendJson(403, array('ok' => false, 'error' => 'key_already_redeemed', 'message' => 'Code déjà activé sur un autre appareil'));
            }
            // Same device → retry-friendly
        }

        // Lookup line
        try {
            $line = \IPS\Db::i()->select('*', 'noun_iptv_lines', array('line_id=?', $key['line_id']))->first();
        } catch (\UnderflowException $e) {
            self::audit($code, $deviceId, 'line_not_found', "line_id={$key['line_id']}");
            self::sendJson(500, array('ok' => false, 'error' => 'line_not_found', 'message' => 'Ligne IPTV introuvable'));
        }

        // Line expiry
        if (!empty($line['expires_at']) && $line['expires_at'] > 0 && $line['expires_at'] < $now) {
            self::audit($code, $deviceId, 'line_expired', '');
            self::sendJson(403, array('ok' => false, 'error' => 'line_expired', 'message' => 'Abonnement IPTV expiré'));
        }

        // Decrypt creds (cipher inline below)
        try {
            $host = self::cipherDecrypt($line['host_enc']);
            $user = self::cipherDecrypt($line['user_enc']);
            $pass = self::cipherDecrypt($line['pass_enc']);
        } catch (\Throwable $e) {
            self::audit($code, $deviceId, 'decrypt_error', $e->getMessage());
            self::sendJson(500, array('ok' => false, 'error' => 'decrypt_error', 'message' => 'Erreur déchiffrement creds'));
        }

        // Mark redeemed + bind device
        if (empty($key['bound_device_id'])) {
            \IPS\Db::i()->update('noun_iptv_keys', array(
                'status'          => 'redeemed',
                'redeemed_at'     => $now,
                'bound_device_id' => $deviceId,
            ), array('code=?', $code));
        }

        self::audit($code, $deviceId, 'success', '');

        self::sendJson(200, array(
            'ok'              => true,
            'host'            => $host,
            'username'        => $user,
            'password'        => $pass,
            'expires_at'      => $line['expires_at'] !== null ? (int)$line['expires_at'] : null,
            'max_connections' => $line['max_connections'] !== null ? (int)$line['max_connections'] : null,
        ));
    }

    /** AES-256-GCM decrypt con HKDF-SHA256 da SUITE_UNIQUE_KEY. Compat con $cipherEncrypt in settings_code. */
    protected static function cipherDecrypt($cipherText)
    {
        $cipherText = (string) $cipherText;
        if ($cipherText === '') return '';

        // Legacy v0 (plain base64)
        if (strpos($cipherText, 'v0:') === 0) {
            return base64_decode(substr($cipherText, 3));
        }
        // Raw passthrough (no prefix)
        if (strpos($cipherText, 'v1:') !== 0) {
            return $cipherText;
        }

        $raw = base64_decode(substr($cipherText, 3));
        if ($raw === false || strlen($raw) < 12 + 16 + 1) {
            throw new \RuntimeException('Cipher: invalid ciphertext format');
        }
        $nonce = substr($raw, 0, 12);
        $tag   = substr($raw, -16);
        $ct    = substr($raw, 12, -16);

        $ikm = defined('\IPS\SUITE_UNIQUE_KEY') ? \IPS\SUITE_UNIQUE_KEY : 'fallback-dev-only';
        $key = hash_hkdf('sha256', $ikm, 32, 'noun-iptv-line-v1', '');
        $plain = openssl_decrypt($ct, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $nonce, $tag, '');
        if ($plain === false) {
            throw new \RuntimeException('Cipher: decrypt failed (tampered or wrong key)');
        }
        return $plain;
    }

    /** Rate-limit per IP: max N failures/h da settings. */
    protected static function rateLimited($ip)
    {
        $limit = max(5, (int)\IPS\Settings::i()->noun_iptv_rate_limit_per_hour);
        $since = time() - 3600;
        try {
            $count = \IPS\Db::i()->select(
                'COUNT(*)',
                'noun_iptv_audit',
                array('ip=? AND ts >= ? AND outcome != ?', $ip, $since, 'success')
            )->first();
            return (int)$count >= $limit;
        } catch (\Throwable $e) {
            return false; // best-effort
        }
    }

    /** Append row in noun_iptv_audit (best-effort). */
    protected static function audit($code, $deviceId, $outcome, $message)
    {
        try {
            \IPS\Db::i()->insert('noun_iptv_audit', array(
                'ts'        => time(),
                'ip'        => isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '0.0.0.0',
                'code'      => $code !== '' ? $code : null,
                'device_id' => $deviceId !== '' ? $deviceId : null,
                'outcome'   => $outcome,
                'message'   => $message,
            ));
        } catch (\Throwable $e) {
            error_log("noun_iptv_keys audit failed: " . $e->getMessage());
        }
    }

    /** Send JSON response + exit. */
    protected static function sendJson($httpCode, array $payload)
    {
        if (!headers_sent()) {
            http_response_code($httpCode);
            header('Content-Type: application/json; charset=utf-8');
            header('Cache-Control: no-store, no-cache, must-revalidate');
            header('X-Content-Type-Options: nosniff');
        }
        echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        exit;
    }
}

plugin.settingsCode:
//<?php
/**
 * NouN IPTV Keys — Admin dashboard semplificato (v2.0.0).
 *
 * Workflow utente:
 *   1. Apri plugin → atterri su tab "Lines"
 *   2. Incolla URL M3U Xtream + Nota cliente → click "Aggiungi + Genera Codice"
 *   3. Plugin parse URL → cifra → INSERT line → INSERT key 16 cifre → mostra codice
 *   4. Consegni il codice al cliente → cliente lo inserisce nell'app TV
 *
 * Tabs visibili: Lines · Keys · Settings.
 * Pattern Mugiwara IPS4: $form pre-iniettato da IPS4, addMessage con $htmlsafe=FALSE
 * per HTML raw, save manuale di settings con $form->values() + saveAsSettings.
 */

if (!\defined('\IPS\SUITE_UNIQUE_KEY')) {
    header(($_SERVER['SERVER_PROTOCOL'] ?? 'HTTP/1.0') . ' 403 Forbidden');
    exit;
}

$tab    = isset(\IPS\Request::i()->ntab)    ? (string) \IPS\Request::i()->ntab    : 'lines';
$action = isset(\IPS\Request::i()->naction) ? (string) \IPS\Request::i()->naction : '';

$baseUrl = function (array $extra = array()) {
    $params = array_merge(array(
        'app'        => 'core',
        'module'     => 'applications',
        'controller' => 'plugins',
        'do'         => 'settings',
        'id'         => (int) \IPS\Request::i()->id,
    ), $extra);
    return (string) \IPS\Http\Url::internal(http_build_query($params), 'admin');
};
$urlTab = function ($t) use ($baseUrl) { return $baseUrl(array('ntab' => $t)); };

// ── Cipher inline (AES-256-GCM con HKDF-SHA256 da SUITE_UNIQUE_KEY) ─────────
// Necessario inline qui perché la classe \IPS\noun_iptv_keys\Cipher è iniettata
// solo nel body dell'hook front-end e NON è disponibile in ACP context.
// Stesso algorithm e info-string del sources/Cipher.php → RedeemHandler può
// decifrare quanto cifrato qui.
$cipherEncrypt = function ($plaintext) {
    if ($plaintext === '') return '';
    $ikm = defined('\IPS\SUITE_UNIQUE_KEY') ? \IPS\SUITE_UNIQUE_KEY : 'fallback-dev-only';
    $key = hash_hkdf('sha256', $ikm, 32, 'noun-iptv-line-v1', '');
    $nonce = random_bytes(12);
    $tag = '';
    $ct = openssl_encrypt($plaintext, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $nonce, $tag, '', 16);
    if ($ct === false) {
        throw new \RuntimeException('Cipher inline: encrypt failed: ' . openssl_error_string());
    }
    return 'v1:' . base64_encode($nonce . $ct . $tag);
};

// ── ACTIONS (mutating, con redirect) ────────────────────────────────────────

if ($action === 'gen_key' && isset(\IPS\Request::i()->line_id)) {
    $lineId = (int) \IPS\Request::i()->line_id;
    try {
        \IPS\Db::i()->select('*', 'noun_iptv_lines', array('line_id=?', $lineId))->first();
        $code = '';
        for ($j = 0; $j < 16; $j++) $code .= random_int(0, 9);
        \IPS\Db::i()->insert('noun_iptv_keys', array(
            'code'       => $code,
            'line_id'    => $lineId,
            'created_at' => time(),
            'status'     => 'active',
            'label'      => null,
        ));
        \IPS\Output::i()->redirect(
            $urlTab('keys') . '&newkey=' . $code,
            'Codice generato'
        );
    } catch (\Throwable $e) {
        $flashError = 'Errore: ' . $e->getMessage();
    }
}

if ($action === 'revoke_key' && isset(\IPS\Request::i()->code)) {
    $c = preg_replace('/\D+/', '', (string) \IPS\Request::i()->code);
    if (strlen($c) === 16) {
        \IPS\Db::i()->update('noun_iptv_keys', array('status' => 'revoked'), array('code=?', $c));
        \IPS\Output::i()->redirect($urlTab('keys'), 'Revocato');
    }
}

if ($action === 'unbind_key' && isset(\IPS\Request::i()->code)) {
    $c = preg_replace('/\D+/', '', (string) \IPS\Request::i()->code);
    if (strlen($c) === 16) {
        \IPS\Db::i()->update('noun_iptv_keys', array(
            'bound_device_id' => null,
            'status'          => 'active',
            'redeemed_at'     => null,
        ), array('code=?', $c));
        \IPS\Output::i()->redirect($urlTab('keys'), 'Device sbloccato');
    }
}

if ($action === 'delete_key' && isset(\IPS\Request::i()->code)) {
    $c = preg_replace('/\D+/', '', (string) \IPS\Request::i()->code);
    if (strlen($c) === 16) {
        \IPS\Db::i()->delete('noun_iptv_keys', array('code=?', $c));
        \IPS\Output::i()->redirect($urlTab('keys'), 'Cancellato');
    }
}

if ($action === 'delete_line' && isset(\IPS\Request::i()->line_id)) {
    $lineId = (int) \IPS\Request::i()->line_id;
    \IPS\Db::i()->delete('noun_iptv_keys', array('line_id=?', $lineId));
    \IPS\Db::i()->delete('noun_iptv_lines', array('line_id=?', $lineId));
    \IPS\Output::i()->redirect($urlTab('lines'), 'Linea cancellata');
}

// ── FORM HANDLING per tab attivo ────────────────────────────────────────────

if ($tab === 'lines') {
    // Form unificato: incolla M3U URL + label → crea linea + key in un colpo.
    $form = new \IPS\Helpers\Form('add_line_form', 'Aggiungi + Genera Codice');
    $form->add(new \IPS\Helpers\Form\Text(
        'label', '', TRUE,
        array('maxLength' => 120, 'placeholder' => 'es. Mario Rossi · Souk Ahras')
    ));
    $form->add(new \IPS\Helpers\Form\Url(
        'm3u_url', '', TRUE,
        array('placeholder' => 'http://line.ir360.eu:8080/get.php?username=X&password=Y&type=m3u_plus')
    ));
    $form->add(new \IPS\Helpers\Form\Date(
        'expires_at', 0, FALSE, array('unlimited' => 0)
    ));
    $form->add(new \IPS\Helpers\Form\TextArea(
        'notes', '', FALSE,
        array('placeholder' => 'Note opzionali (telefono, data pagamento, ecc.)')
    ));

    if ($values = $form->values()) {
        try {
            $parts = parse_url((string) $values['m3u_url']);
            if (empty($parts['host']) || empty($parts['query'])) {
                throw new \InvalidArgumentException('URL malformato. Atteso /get.php?username=X&password=Y&type=m3u_plus');
            }
            parse_str($parts['query'], $q);
            $user = isset($q['username']) ? trim((string) $q['username']) : '';
            $pass = isset($q['password']) ? trim((string) $q['password']) : '';
            if ($user === '' || $pass === '') {
                throw new \InvalidArgumentException('username o password mancanti nella query string');
            }
            $scheme = isset($parts['scheme']) ? strtolower($parts['scheme']) : 'http';
            $port = isset($parts['port']) ? (int) $parts['port'] : ($scheme === 'https' ? 443 : 80);
            $portPart = (
                ($scheme === 'http' && $port === 80) ||
                ($scheme === 'https' && $port === 443)
            ) ? '' : ":$port";
            $host = "$scheme://{$parts['host']}$portPart";

            // INSERT linea (host/user/pass cifrati AES-256-GCM inline)
            $lineId = \IPS\Db::i()->insert('noun_iptv_lines', array(
                'label'           => (string) $values['label'],
                'server_id'       => null,
                'host_enc'        => $cipherEncrypt($host),
                'user_enc'        => $cipherEncrypt($user),
                'pass_enc'        => $cipherEncrypt($pass),
                'expires_at'      => $values['expires_at'] instanceof \IPS\DateTime ? $values['expires_at']->getTimestamp() : null,
                'max_connections' => 1,
                'notes'           => $values['notes'] ?: null,
                'created_at'      => time(),
            ));

            // INSERT key 16 cifre crypto-secure
            $code = '';
            for ($j = 0; $j < 16; $j++) $code .= random_int(0, 9);
            \IPS\Db::i()->insert('noun_iptv_keys', array(
                'code'       => $code,
                'line_id'    => $lineId,
                'created_at' => time(),
                'status'     => 'active',
                'label'      => (string) $values['label'],
            ));

            // Log success
            try { \IPS\Log::log("Created line #$lineId + key $code for: " . $values['label'], 'noun_iptv_keys'); } catch (\Throwable $e) {}

            // Redirect → mostra codice generato
            \IPS\Output::i()->redirect(
                $urlTab('keys') . '&newkey=' . $code,
                'Linea creata + codice generato'
            );
        } catch (\Throwable $e) {
            try { \IPS\Log::log($e, 'noun_iptv_keys'); } catch (\Throwable $ee) {}
            $form->error = 'Errore: ' . $e->getMessage();
        }
    }
} elseif ($tab === 'settings') {
    $form->addHeader('Sicurezza HMAC');
    $form->add(new \IPS\Helpers\Form\Text(
        'noun_iptv_shared_secret',
        (string) \IPS\Settings::i()->noun_iptv_shared_secret,
        TRUE,
        array('size' => 100, 'placeholder' => 'Genera con: openssl rand -hex 32')
    ));
    $form->add(new \IPS\Helpers\Form\Number(
        'noun_iptv_replay_window_sec',
        (int) \IPS\Settings::i()->noun_iptv_replay_window_sec ?: 300,
        TRUE,
        array('min' => 60, 'max' => 3600),
        NULL, NULL, 'sec'
    ));
    $form->addHeader('Rate limit');
    $form->add(new \IPS\Helpers\Form\Number(
        'noun_iptv_rate_limit_per_hour',
        (int) \IPS\Settings::i()->noun_iptv_rate_limit_per_hour ?: 20,
        TRUE,
        array('min' => 5, 'max' => 1000),
        NULL, NULL, 'failures/h'
    ));
    // Save manuale: IPS4 NON salva automaticamente settings su settingsCode
    // a meno che il file XML del plugin specifichi un saveSettings handler.
    // Più affidabile gestire qui.
    if ($values = $form->values()) {
        $form->saveAsSettings($values);
        \IPS\Output::i()->redirect($urlTab('settings'), 'Settings salvate');
    }
}

// ── TABS NAV (HTML raw) ─────────────────────────────────────────────────────

$tabs = array(
    'lines'    => 'Lines',
    'keys'     => 'Keys',
    'settings' => 'Settings',
);
$tabNav = '<div style="display:flex;gap:4px;margin:0 0 22px;border-bottom:1px solid #2a2a2a;">';
foreach ($tabs as $key => $label) {
    $sel = $tab === $key;
    $bg     = $sel ? '#1565c0' : 'transparent';
    $col    = $sel ? '#fff'    : '#999';
    $border = $sel ? 'border-bottom:2px solid #1565c0;' : 'border-bottom:2px solid transparent;';
    $tabNav .= sprintf(
        '<a href="%s" style="display:inline-block;padding:10px 22px;background:%s;color:%s;%s text-decoration:none;font-weight:600;font-size:13px;letter-spacing:1px;text-transform:uppercase;">%s</a>',
        htmlspecialchars($urlTab($key), ENT_QUOTES),
        $bg, $col, $border, $label
    );
}
$tabNav .= '</div>';

// ── TAB CONTENT (HTML raw, iniettato via addMessage) ───────────────────────

$content = $tabNav;

if (!empty($flashError ?? '')) {
    $content .= '<div style="background:#5a1818;color:#fff;padding:12px;border-radius:6px;margin-bottom:14px;">'
        . htmlspecialchars($flashError, ENT_QUOTES) . '</div>';
}

switch ($tab) {
    case 'lines':
        $content .= '<h2 style="margin:0 0 6px;">Aggiungi Linea + Genera Codice</h2>';
        $content .= '<p style="color:#888;margin:0 0 16px;">Incolla l\'URL M3U Xtream del provider, dai un nome al cliente, click. Plugin estrae host/user/pass, cifra AES-256-GCM, crea linea e genera codice 16 cifre da consegnare al cliente.</p>';
        // sotto il form (renderizzato auto da IPS4) appende la tabella
        $linesTable = '<h2 style="margin:36px 0 12px;">Linee attive</h2>';
        $linesTable .= '<table style="width:100%;border-collapse:collapse;background:#1a1a1a;border-radius:6px;overflow:hidden;">';
        $linesTable .= '<tr style="background:#2a2a2a;color:#aaa;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:1px;">'
            . '<th style="padding:10px;">ID</th>'
            . '<th style="padding:10px;">Cliente</th>'
            . '<th style="padding:10px;">Scadenza</th>'
            . '<th style="padding:10px;">Creata</th>'
            . '<th style="padding:10px;"># Keys</th>'
            . '<th style="padding:10px;">Azioni</th></tr>';
        $count = 0;
        foreach (\IPS\Db::i()->select('*', 'noun_iptv_lines', NULL, 'created_at DESC LIMIT 50') as $line) {
            $count++;
            $nKeys = (int) \IPS\Db::i()->select('COUNT(*)', 'noun_iptv_keys', array('line_id=?', $line['line_id']))->first();
            $exp = $line['expires_at'] ? date('d/m/Y', (int) $line['expires_at']) : '—';
            $created = date('d/m/Y H:i', (int) $line['created_at']);
            $genUrl = $baseUrl(array('naction' => 'gen_key', 'line_id' => $line['line_id']));
            $delUrl = $baseUrl(array('naction' => 'delete_line', 'line_id' => $line['line_id']));
            $linesTable .= sprintf(
                '<tr style="border-bottom:1px solid #2a2a2a;color:#ddd;">'
                . '<td style="padding:10px;"><code>#%d</code></td>'
                . '<td style="padding:10px;"><strong>%s</strong></td>'
                . '<td style="padding:10px;">%s</td>'
                . '<td style="padding:10px;color:#888;">%s</td>'
                . '<td style="padding:10px;"><strong>%d</strong></td>'
                . '<td style="padding:10px;">'
                . '<a href="%s" style="background:#2e7d32;color:#fff;padding:6px 12px;border-radius:4px;text-decoration:none;margin-right:6px;font-size:11px;">+ Codice extra</a>'
                . '<a href="%s" onclick="return confirm(\'Cancellare linea? Tutti i codici collegati verranno cancellati.\')" style="background:#5a1818;color:#fff;padding:6px 12px;border-radius:4px;text-decoration:none;font-size:11px;">Elimina</a>'
                . '</td></tr>',
                $line['line_id'],
                htmlspecialchars($line['label'] ?: '—', ENT_QUOTES),
                $exp, $created, $nKeys,
                htmlspecialchars($genUrl, ENT_QUOTES),
                htmlspecialchars($delUrl, ENT_QUOTES)
            );
        }
        if ($count === 0) {
            $linesTable .= '<tr><td colspan="6" style="padding:30px;text-align:center;color:#666;">Nessuna linea ancora. Incolla URL sopra e clicca per crearne una.</td></tr>';
        }
        $linesTable .= '</table>';
        // append tabella DOPO il form (IPS4 renderizza prima la message, poi i field, poi NIENTE altro)
        // → soluzione: aggiungere la tabella come una SECONDA addMessage chiamata DOPO il form
        $linesTableHtml = $linesTable;
        break;

    case 'keys':
        $newKey = isset(\IPS\Request::i()->newkey) ? preg_replace('/\D+/', '', (string) \IPS\Request::i()->newkey) : '';
        if (strlen($newKey) === 16) {
            $formatted = substr($newKey, 0, 4) . '-' . substr($newKey, 4, 4) . '-' . substr($newKey, 8, 4) . '-' . substr($newKey, 12, 4);
            $content .= '<div style="background:linear-gradient(135deg,#0a3d1f 0%,#0f2547 100%);padding:30px;border-radius:10px;margin-bottom:28px;text-align:center;border:1px solid #2e7d32;">';
            $content .= '<p style="margin:0 0 12px;color:#aaa;letter-spacing:3px;text-transform:uppercase;font-size:11px;">Codice generato · da consegnare al cliente</p>';
            $content .= '<h1 style="margin:0;font-family:monospace;font-size:42px;letter-spacing:8px;color:#e6a700;font-weight:900;">' . $formatted . '</h1>';
            $content .= '<p style="margin:14px 0 0;color:#888;font-size:12px;">Il cliente inserisce questo codice sull\'app NounStream IPTV → login automatico</p>';
            $content .= '</div>';
        }
        $content .= '<h2 style="margin:0 0 14px;">Codici generati</h2>';
        $content .= '<table style="width:100%;border-collapse:collapse;background:#1a1a1a;border-radius:6px;overflow:hidden;">';
        $content .= '<tr style="background:#2a2a2a;color:#aaa;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:1px;">'
            . '<th style="padding:10px;">Codice</th>'
            . '<th style="padding:10px;">Cliente</th>'
            . '<th style="padding:10px;">Status</th>'
            . '<th style="padding:10px;">Creato</th>'
            . '<th style="padding:10px;">Usato il</th>'
            . '<th style="padding:10px;">Device</th>'
            . '<th style="padding:10px;">Azioni</th></tr>';
        $count = 0;
        foreach (\IPS\Db::i()->select('*', 'noun_iptv_keys', NULL, 'created_at DESC LIMIT 100') as $k) {
            $count++;
            $codeFmt = substr($k['code'], 0, 4) . '-' . substr($k['code'], 4, 4) . '-' . substr($k['code'], 8, 4) . '-' . substr($k['code'], 12, 4);
            $created = date('d/m/Y', (int) $k['created_at']);
            $redeemed = $k['redeemed_at'] ? date('d/m/Y H:i', (int) $k['redeemed_at']) : '—';
            $dev = $k['bound_device_id'] ? '<code>' . substr($k['bound_device_id'], 0, 10) . '…</code>' : '—';
            $statusMap = array(
                'active'   => '#2e7d32',
                'redeemed' => '#1565c0',
                'revoked'  => '#5a1818',
                'expired'  => '#888',
            );
            $statusColor = $statusMap[$k['status']] ?? '#888';
            $unbindBtn = $k['bound_device_id'] ? sprintf(
                '<a href="%s" onclick="return confirm(\'Reset device? Il cliente potrà riusare lo stesso codice sul nuovo device. Il vecchio device perderà accesso.\')" title="Reset binding device — il codice torna usabile su nuovo device" style="background:#e6a700;color:#000;padding:5px 10px;border-radius:4px;text-decoration:none;margin-right:4px;font-size:11px;font-weight:600;">Reset device</a>',
                htmlspecialchars($baseUrl(array('naction' => 'unbind_key', 'code' => $k['code'])), ENT_QUOTES)
            ) : '';
            $revokeBtn = $k['status'] !== 'revoked' ? sprintf(
                '<a href="%s" onclick="return confirm(\'Revocare il codice?\')" style="background:#5a1818;color:#fff;padding:5px 10px;border-radius:4px;text-decoration:none;margin-right:4px;font-size:11px;">Revoca</a>',
                htmlspecialchars($baseUrl(array('naction' => 'revoke_key', 'code' => $k['code'])), ENT_QUOTES)
            ) : '';
            $delBtn = sprintf(
                '<a href="%s" onclick="return confirm(\'Cancella?\')" style="background:#2a2a2a;color:#fff;padding:5px 10px;border-radius:4px;text-decoration:none;font-size:11px;">Del</a>',
                htmlspecialchars($baseUrl(array('naction' => 'delete_key', 'code' => $k['code'])), ENT_QUOTES)
            );
            $content .= sprintf(
                '<tr style="border-bottom:1px solid #2a2a2a;color:#ddd;">'
                . '<td style="padding:10px;font-family:monospace;letter-spacing:1px;font-size:13px;color:#e6a700;">%s</td>'
                . '<td style="padding:10px;"><strong>%s</strong></td>'
                . '<td style="padding:10px;"><span style="background:%s;color:#fff;padding:3px 8px;border-radius:3px;font-size:10px;text-transform:uppercase;letter-spacing:1px;">%s</span></td>'
                . '<td style="padding:10px;color:#888;">%s</td>'
                . '<td style="padding:10px;color:#888;">%s</td>'
                . '<td style="padding:10px;">%s</td>'
                . '<td style="padding:10px;">%s%s%s</td></tr>',
                $codeFmt,
                htmlspecialchars($k['label'] ?: '—', ENT_QUOTES),
                $statusColor, $k['status'],
                $created, $redeemed, $dev,
                $unbindBtn, $revokeBtn, $delBtn
            );
        }
        if ($count === 0) {
            $content .= '<tr><td colspan="7" style="padding:30px;text-align:center;color:#666;">Nessun codice ancora generato.</td></tr>';
        }
        $content .= '</table>';
        break;

    case 'settings':
        $content .= '<h2 style="margin:0 0 6px;">Configurazione sicurezza</h2>';
        $content .= '<p style="color:#888;margin:0 0 16px;">Shared secret HMAC + finestra anti-replay + rate limit per IP. Lo shared_secret DEVE coincidere col valore nell\'app TV (<code>local.properties → noun.hmac.secret</code>).</p>';
        break;
}

// ── INIEZIONE NEL $form pre-iniettato ───────────────────────────────────────
// IPS4 renderizza $form alla fine del settingsCode. addMessage($html, $type,
// $htmlsafe=FALSE) inietta HTML raw che appare PRIMA dei field nel render.
// Per la tabella sotto al form di tab=lines, secondo addMessage.

$form->addMessage($content, 'info', FALSE);

if (!empty($linesTableHtml ?? '')) {
    $form->addMessage($linesTableHtml, 'info', FALSE);
}

