//<?php /** * NouN IPTV Keys — DDL install. * * Crea le 2 tabelle del plugin: * - noun_iptv_lines: linee IPTV (Xtream creds at rest, criptate AES-256-GCM) * - noun_iptv_keys: codici 16 cifre + binding device_id * - noun_iptv_audit: log redeem (debugging + anti-abuse forense) */
$schema = array( // 1.1.0 — Pool server Xtream condivisi (pattern Mugiwara). // Admin crea server una volta, poi su Add Line sceglie da dropdown. array( 'name' => 'noun_iptv_servers', 'columns' => array( 'server_id' => array('name' => 'server_id', 'type' => 'INT', 'unsigned' => true, 'auto_increment' => true), 'name' => array('name' => 'name', 'type' => 'VARCHAR', 'length' => 120, 'null' => false), 'base_url' => array('name' => 'base_url', 'type' => 'VARCHAR', 'length' => 255, 'null' => false), 'active' => array('name' => 'active', 'type' => 'TINYINT', 'unsigned' => true, 'null' => false, 'default' => 1), 'notes' => array('name' => 'notes', 'type' => 'TEXT', 'null' => true), 'created_at' => array('name' => 'created_at', 'type' => 'INT', 'unsigned' => true, 'null' => false), ), 'indexes' => array( 'PRIMARY' => array('type' => 'primary', 'name' => 'PRIMARY', 'columns' => array('server_id')), 'active' => array('type' => 'key', 'name' => 'active', 'columns' => array('active')), ), ), array( 'name' => 'noun_iptv_lines', 'columns' => array( 'line_id' => array('name' => 'line_id', 'type' => 'INT', 'unsigned' => true, 'auto_increment' => true), 'label' => array('name' => 'label', 'type' => 'VARCHAR', 'length' => 120, 'null' => true), 'server_id' => array('name' => 'server_id', 'type' => 'INT', 'unsigned' => true, 'null' => true), // 1.1.0 — FK noun_iptv_servers 'host_enc' => array('name' => 'host_enc', 'type' => 'TEXT', 'null' => false), 'user_enc' => array('name' => 'user_enc', 'type' => 'TEXT', 'null' => false), 'pass_enc' => array('name' => 'pass_enc', 'type' => 'TEXT', 'null' => false), 'expires_at' => array('name' => 'expires_at', 'type' => 'INT', 'unsigned' => true, 'null' => true), 'max_connections' => array('name' => 'max_connections', 'type' => 'TINYINT', 'unsigned' => true, 'null' => true), 'notes' => array('name' => 'notes', 'type' => 'TEXT', 'null' => true), 'created_at' => array('name' => 'created_at', 'type' => 'INT', 'unsigned' => true, 'null' => false), ), 'indexes' => array( 'PRIMARY' => array('type' => 'primary', 'name' => 'PRIMARY', 'columns' => array('line_id')), 'expires_at' => array('type' => 'key', 'name' => 'expires_at', 'columns' => array('expires_at')), ), ), array( 'name' => 'noun_iptv_keys', 'columns' => array( 'code' => array('name' => 'code', 'type' => 'VARCHAR', 'length' => 16, 'null' => false), 'line_id' => array('name' => 'line_id', 'type' => 'INT', 'unsigned' => true, 'null' => false), 'bound_device_id' => array('name' => 'bound_device_id', 'type' => 'VARCHAR', 'length' => 64, 'null' => true), 'created_at' => array('name' => 'created_at', 'type' => 'INT', 'unsigned' => true, 'null' => false), 'redeemed_at' => array('name' => 'redeemed_at', 'type' => 'INT', 'unsigned' => true, 'null' => true), 'expires_at' => array('name' => 'expires_at', 'type' => 'INT', 'unsigned' => true, 'null' => true), 'status' => array('name' => 'status', 'type' => 'ENUM', 'values' => array('active', 'redeemed', 'revoked', 'expired'), 'null' => false, 'default' => 'active'), 'label' => array('name' => 'label', 'type' => 'VARCHAR', 'length' => 120, 'null' => true), ), 'indexes' => array( 'PRIMARY' => array('type' => 'primary', 'name' => 'PRIMARY', 'columns' => array('code')), 'line_id' => array('type' => 'key', 'name' => 'line_id', 'columns' => array('line_id')), 'status' => array('type' => 'key', 'name' => 'status', 'columns' => array('status')), 'bound_device_id' => array('type' => 'key', 'name' => 'bound_device_id', 'columns' => array('bound_device_id')), ), ), array( 'name' => 'noun_iptv_audit', 'columns' => array( 'id' => array('name' => 'id', 'type' => 'BIGINT', 'unsigned' => true, 'auto_increment' => true), 'ts' => array('name' => 'ts', 'type' => 'INT', 'unsigned' => true, 'null' => false), 'ip' => array('name' => 'ip', 'type' => 'VARCHAR', 'length' => 45, 'null' => false), 'code' => array('name' => 'code', 'type' => 'VARCHAR', 'length' => 16, 'null' => true), 'device_id' => array('name' => 'device_id', 'type' => 'VARCHAR', 'length' => 64, 'null' => true), 'outcome' => array('name' => 'outcome', 'type' => 'VARCHAR', 'length' => 40, 'null' => false), // success | invalid_signature | key_not_found | ... 'message' => array('name' => 'message', 'type' => 'TEXT', 'null' => true), ), 'indexes' => array( 'PRIMARY' => array('type' => 'primary', 'name' => 'PRIMARY', 'columns' => array('id')), 'ts' => array('type' => 'key', 'name' => 'ts', 'columns' => array('ts')), 'ip' => array('type' => 'key', 'name' => 'ip', 'columns' => array('ip')), 'outcome' => array('type' => 'key', 'name' => 'outcome', 'columns' => array('outcome')), ), ), );
foreach ($schema as $table) { if (!\IPS\Db::i()->checkForTable($table['name'])) { \IPS\Db::i()->createTable($table); } }
return TRUE;
